from fractions import Fraction
from random import Random

import ledger

rng = Random(163)
checks = 3000
expense_count = 0


def decimal_text(coefficient, places):
    integer, fraction = divmod(coefficient, 10**places)
    if not places:
        return str(integer)
    return f\"{integer}.{fraction:0{places}d}\"


def reference_apportion(cents, weights):
    total_weight = sum(weights.values())
    fractions = {name: Fraction(cents * weight, total_weight) for name, weight in weights.items()}
    costs = {name: int(quota) for name, quota in fractions.items()}
    ranking = sorted(costs, key=lambda name: (costs[name] - fractions[name], name))
    for name in ranking[:cents - sum(costs.values())]:
        costs[name] += 1
    return costs


def reference_settlement(balances):
    net = balances.copy()
    transfers = []
    while any(net.values()):
        debtor = min(net, key=lambda name: (net[name], name))
        creditor = min(net, key=lambda name: (-net[name], name))
        cents = min(-net[debtor], net[creditor])
        net[debtor] += cents
        net[creditor] -= cents
        transfers.append((debtor, creditor, cents))
    return transfers


for trial in range(checks):
    names = [f\"member{i:02}\" for i in range(rng.randrange(1, 15))]
    rng.shuffle(names)
    balances = dict.fromkeys(names, 0)
    precisions = (rng.randrange(41), rng.randrange(41))
    rates = {
        \"EuR\": decimal_text(rng.randrange(1, 7 * 10**precisions[0]), precisions[0]),
        \"gBp\": decimal_text(rng.randrange(1, 7 * 10**precisions[1]), precisions[1]),
        \"cAd\": \"0.5\",
    }
    reference_rates = {code.upper(): Fraction(rate) for code, rate in rates.items()}
    group = {\"currency\": \"uSd\", \"rates\": rates, \"members\": [name.upper() for name in names], \"expenses\": []}

    for index in range(rng.randrange(1, 15)):
        currency = rng.choice([None, \"UsD\", \"EUR\", \"GBP\", \"CaD\"])
        payer = rng.choice(names)
        participants = rng.sample(names, rng.randrange(1, len(names) + 1))
        amount = rng.choice([rng.randrange(1, 20), rng.randrange(1, 10**35)])
        converted = amount
        if currency and currency.upper() "'!= "USD":
            converted = round(amount * reference_rates[currency.upper()])

        kinds = ["equal", "percent", "shares"]
        if not currency or currency.upper() == "USD":
            kinds.append("exact")
        kind = rng.choice(kinds)
        split = {"type": kind}
        if kind == "exact":
            cuts = sorted(rng.choices(range(1001), k=len(participants) - 1))
            scaled = [0, *(amount * cut // 1000 for cut in cuts), amount]
            costs = {name: right - left for name, left, right in zip(participants, scaled, scaled[1:])}
            split["amounts"] = {name.upper(): decimal_text(value, 2) for name, value in costs.items()}
        else:
            if kind == "equal":
                weights = dict.fromkeys(participants, 1)
                split["among"] = [name.upper() for name in participants]
            elif kind == "percent":
                cuts = [0, *sorted(rng.sample(range(1, 10000), len(participants) - 1)), 10000]
                weights = {name: right - left for name, left, right in zip(participants, cuts, cuts[1:])}
                split["percents"] = {name.upper(): decimal_text(weight, 2) for name, weight in weights.items()}
            else:
                weights = {name: rng.choice([rng.randrange(1, 10), rng.randrange(1, 10**35)]) for name in participants}
                split["shares"] = {name.upper(): weight for name, weight in weights.items()}
            costs = reference_apportion(converted, weights)

        expense = {"id": str(index), "payer": payer.upper(), "amount": decimal_text(amount, 2), "split": split}
        if currency:
            expense["currency"] = currency
        group["expenses"].append(expense)
        balances[payer] += converted
        for name, cost in costs.items():
            balances[name] -= cost
        expense_count += 1

    assert sum(balances.values()) == 0, trial
    assert ledger.balances(group) == balances, trial
    assert ledger.settle(group) == reference_settlement(balances), trial

print(f"{checks} randomized groups and {expense_count} expenses matched independent Fraction-based conversion, splitting, and settlement.")
